//! The built-in texts, "Mewrk concise": what the host says when no
//! tool-description file overrides a key.
//!
//! They keep only what a frontier model cannot infer and that changes what it
//! does — host-specific lifecycle, result shapes it must reference, limits the
//! schema cannot express — and say nothing where a tool's name and schema
//! already do. File and shell tools carry no description because their names
//! say what they are. They ship with the build and change with it; nothing copies
//! them to disk.
//!
//! One arm per key, exhaustive and in registry order: a literal is the text,
//! `""` says nothing at that point, and `(as Key)` — for a tool variant (see
//! `crate::tool_surface`) whose wording has nothing its variants differ on, or
//! a parameter that says what its sibling says (`preview_wait`'s region) —
//! reads what `Key` says. A key added to the registry therefore needs its text
//! here before it compiles.

use super::PromptKey;

macro_rules! concise_texts {
    ($( $variant:ident => $value:tt ),* $(,)?) => {
        /// The built-in text for `key`.
        pub(super) fn text(key: PromptKey) -> &'static str {
            match key {
                $( PromptKey::$variant => concise_texts!(@value $value), )*
            }
        }

        /// The variants in the order this table lists them, for the order test.
        #[cfg(test)]
        pub(super) const ORDER: &[PromptKey] = &[ $( PromptKey::$variant, )* ];
    };
    // Another variant of the same tool whose text says nothing the two
    // variants differ on: this key reads exactly what that key says.
    (@value (as $other:ident)) => { text(PromptKey::$other) };
    (@value $text:literal) => { $text };
}

